using System;using System.Collections.Generic;using System.Collections.ObjectModel;using WildsEngine.Discoveries.Abstractions.Narratives;using WildsEngine.Discoveries.Base;
namespace WildsEngine.Discoveries.Narratives { public sealed class DiscoveryNarrativeRegistration:IdentifierBase,IDiscoveryNarrativeRegistration { public DiscoveryNarrativeRegistration(Guid id,IDiscoveryNarrativeProfile p,DateTimeOffset at):base(id,"narrative-registration-"+id.ToString("N")){ProfileId=p.Id;ProfileSlug=p.Slug;ProfileVersion=p.Version;Scope=p.Scope;RegisteredAt=at;CompositionPolicyId=p.CompositionPolicy.Id;MetricId=p.Metric.Id;var ids=new Guid[p.Relationships.Count];for(var i=0;i<ids.Length;i++)ids[i]=p.Relationships[i].Id;RelationshipIds=new ReadOnlyCollection<Guid>(ids);}public Guid ProfileId{get;}public string ProfileSlug{get;}public string ProfileVersion{get;}public string Scope{get;}public DateTimeOffset RegisteredAt{get;}public Guid CompositionPolicyId{get;}public Guid MetricId{get;}public IReadOnlyList<Guid> RelationshipIds{get;} } }
